"use client";

import { useQuery } from "convex/react";
import { api } from "@convex/api";

export default function RedemptionsPage() {
  const redemptions = useQuery(api.admin.listRedemptions);

  return (
    <div>
      <h1 style={{ fontSize: 24, fontWeight: 700, marginBottom: 20 }}>Redemptions</h1>
      <div className="card">
        <table>
          <thead>
            <tr>
              <th>User</th>
              <th>Amount</th>
              <th>Paid With</th>
              <th>Phone</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {redemptions?.map((r) => (
              <tr key={r._id}>
                <td style={{ fontFamily: "monospace", fontSize: 12 }}>{r.userId.slice(0, 16)}…</td>
                <td>{r.amount}</td>
                <td>{r.paidWith}</td>
                <td>{r.phoneNumber}</td>
                <td>
                  <span className={`badge ${r.status === "fulfilled" ? "badge-green" : r.status === "failed" ? "badge-red" : "badge-yellow"}`}>
                    {r.status}
                  </span>
                </td>
              </tr>
            ))}
            {(!redemptions || redemptions.length === 0) && (
              <tr><td colSpan={5} style={{ color: "#71717a", textAlign: "center", padding: 20 }}>No redemptions yet</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
